templates.template:
.p-navEl-splitTrigger {
	margin-left: -((@xf-publicNavPaddingH) / 1.5);
}
#XF .p-navEl-link.p-navEl-link--splitMenu{
	padding-right: @xf-publicNavPaddingH;
}

//Header
<xf:if is="(property('arp_headerAnimation'))">
@keyframes animation-header-change {
    0% {
        background-image: url('/styles/PHANTOM RP/Image/new year/blue.jpg')
    }

    25% {
        background-image: url('/styles/PHANTOM RP/Image/new year/red.jpg')
    }

    50% {
        background-image: url('/styles/PHANTOM RP/Image/new year/purple.jpg')
    }

    75% {
        background-image: url('/styles/PHANTOM RP/Image/new year/rose.jpg')
    }

	100% {
		background-image: url('/styles/PHANTOM RP/Image/new year/blue.jpg')
	}
}
</xf:if>

<xf:if is="(property('arp_headerOnMobile'))">
@media (max-width: @xf-responsiveMedium)
{
	.p-header
	{
		display: none !important;
	}
}
</xf:if>
//Header
.p-header
{
	.p-header--navigation
	{
		display: flex;
		width: 800px;
		justify-content: center;
		margin: 30px auto 0;

		.p-header-navigation--item
		{
			backdrop-filter: blur(2px) saturate(100%);
    		position: relative;
    		color: @xf-arp_headerLinksColor;
    		font-size: 14px;
    		text-transform: uppercase;
    		letter-spacing: -0.5px;
    		transition: color 100ms ease;
			margin: 0 18px;
    		user-select: none;

			&:hover
			{
				color: @xf-arp_headerLinksHoverColor;
			}
			&:active
			{
				color: white;
			}
		}

		@media (max-width: @xf-responsiveMedium)
		{
			display: none;
		}
	}

	.p-header--hatf
	{
		opacity: 0;
    	display: flex;
    	margin: 50px 0px 60px;
    	flex-direction: column;
    	justify-content: center;
    	align-items: center;

		.p-header-hatf--title
		{
			color: white;
    		font-size: 35px;
    		line-height: 38px;
    		font-weight: bold;
    		text-transform: uppercase;
		}

		.p-header-hatf--subtitle
		{
			color: #FFFFFF;
    		font-size: 14px;
    		font-weight: bold;
    		text-transform: uppercase;
		}
	}
}

.p-navgroup-linkText
{
	margin-left: 8px;
}

//Footer
.footer
{
	display: flex;
    position: relative;
    flex-direction: column;
    border-top: 1px solid #ededed;
    margin-top: auto;

	.fixed-size
	{
		width: 100%;
    	padding: 80px 20px;
    	max-width: 1170px;
    	box-sizing: border-box;
    	margin: 0 auto;
	}

	.footer-container
	{
		margin-bottom: 65px;

		&:last-child
		{
			margin-bottom: 0
		}
	}

	.footer-copyright
	{
		display: flex;
    	justify-content: space-between;
    	align-items: flex-end;

		.footer-copyright__text
		{
			display: unset;
    		font-size: 16px;
    		font-weight: normal;
    		color: @xf-arp_footerAboutUsColor;
    		line-height: 1.8;
    		max-width: 545px;
    		margin: unset;
    		margin-block-start: unset;
    		margin-block-end: unset;
		}

		.footer-copyright__caption
		{
			font-size: 16px;
    		color: rgba(0, 0, 0, 0.6);
		}
	}

	.footer-navigation
	{
		display: flex;
    	align-items: flex-start;
    	justify-content: space-between;

		.footer-navigation__section
		{
			display: flex;
    		flex-direction: column;

			.footer-navigation__section__title
			{
				font-size: 24px;
    			font-weight: bold;
    			line-height: 20px;
   	 			margin-bottom: 25px;
			}
		}

		.footer-navigation__logotype img
		{
			display: block;
    		min-height: 39px;
    		margin-bottom: 10px;

			&:active 
			{
				position: relative;
    			top: 1px
			}
		}

		.footer-navigation__section__items
		{
			display: flex;
    		flex-direction: column;

			.footer-navigation__section__items__item
			{
				font-size: 16px;
    			line-height: 35px;
    			transition: opacity 300ms ease;

				&:hover
				{
					opacity: 0.8;
				}
			}
		}

		.footer-navigation__section__networks 
		{
			display: grid;
    		grid-template-rows: repeat(2, 84px);
    		grid-template-columns: repeat(3, 84px);
    		row-gap: 16px;
    		column-gap: 16px;

			.footer-navigation__section__networks__item
			{
				display: flex;
    			flex-direction: column;
    			justify-content: center;
    			align-items: center;
    			background-repeat: no-repeat;
    			background-size: 30px 30px, cover;
    			background-position: center;
    			border-radius: 6px;
    			transition: transform 300ms ease;
    			cursor: pointer;

				&:hover
				{
					transform: scale(1.05);
				}

				&.network-telegram
				{
					background-image: url('styles/PHANTOM RP/Image/telegram.svg'), linear-gradient(-45deg, #03a9f4 0%, #42c4ff 100%);
				}

				&.network-vk 
				{
					background-image: url('styles/PHANTOM RP/Image/vk-white.svg'), linear-gradient(-45deg, #4a76a8 0%, #73b4fd 100%);
				}

				&.network-ok
				{
					background-size: 42px 42px, cover;
    				background-image: url('styles/PHANTOM RP/Image/ok.svg'), linear-gradient(-45deg, #f80 0%, #f80 100%);
				}

				&.network-discrod
				{
					background-image: url('styles/PHANTOM RP/Image/discord.svg'), linear-gradient(0deg, #7289da 0%, #b9c8ff 100%);
				}

				&.network-youtube
				{
					background-image: url('styles/PHANTOM RP/Image/youtube.svg'), linear-gradient(-45deg, #e53935 0%, #e5356a 100%)
				}

				&.network-tiktok
				{
					background-image: url('styles/PHANTOM RP/Image/tiktok.svg'), linear-gradient(135deg, #25f4ee 0%, #fe2c55 100%);
				}
			}
		}
	}
}

@media (max-width: @xf-responsiveMedium)
{
	<xf:if is="(property('arp_footerMobileEnable'))">
	.fixed-size
	{
		display: none;
	}
	</xf:if>
	.footer-navigation
	{
		flex-direction:column;

		.footer-navigation__section
		{
			margin-bottom: 50px;

			&:last-child
			{
				margin-bottom: unset;
			}
		}

		.footer-navigation__section__networks
		{
			grid-template-rows:repeat(2, 70px) !important;
        	grid-template-columns: repeat(3, 70px) !important;
        	column-gap: 10px !important;
        	row-gap: 10px !important
		}
	}

	.footer-copyright
	{
		flex-direction: column;
        align-items: flex-start !important;

		.footer-copyright__text
		{
			margin-bottom: 20px !important;
		}
	}
}


//Thread
<xf:if is="(property('arp_animationThread'))">
.structItem:hover {
    transform: scale(1.01);
    -webkit-box-shadow: 0px 0px 10px 0px rgba(34, 60, 80, 0.3);
    -moz-box-shadow: 0px 0px 10px 0px rgba(34, 60, 80, 0.3);
    box-shadow: 0px 0px 10px 0px rgba(34, 60, 80, 0.3);
    background: #fff;
}
</xf:if>

// ######################################### MAIN BODY #################################

html.has-os-ios.has-displaymodestandalone
{
	// prevent overscroll entirely on iOS in display-mode: standalone
	overscroll-behavior-y: none !important;

	.iosRefresh-ptr
	{
		background-color: @xf-publicHeader--background-color;
	}

	.iosRefresh-icon, .iosRefresh-text
	{
		color: @xf-chromeTextColor;
	}
}

.p-body
{
	display: flex;
	align-items: stretch;
	flex-grow: 1;
	min-height: 1px; // IE11 workaround - related to #139187
}

.p-body-inner
{
	display: flex;
	flex-direction: column;
	width: 100%;

	.m-pageWidth();
	.m-clearFix();
}

.p-body-header
{
	margin-bottom: 30px;
}

.p-body-main
{
	display: table;
	table-layout: fixed;
	width: 100%;
	margin-bottom: 80px;
	min-height: 1px; // IE11 workaround - related to #139187
}

.p-body-content
{
	display: table-cell;
	vertical-align: top;

	.p-body-main--withSideNav &
	{
		padding-left: @xf-sidebarSpacer;
	}

	.p-body-main--withSidebar &
	{
		padding-right: @xf-sidebarSpacer;
	}

	.p-body-main--withSidebar &,
	.p-body-main--withSideNav &
	{
		// don't let the ad overflow the sidebar area -- this can happen due to how the Adsense JS works
		ins.adsbygoogle
		{
			// -10px gives a little buffer or helps account for no scrollbar being considered
			max-width: calc(~'100vw - 10px - @{xf-pageEdgeSpacer} - @{xf-pageEdgeSpacer} - @{xf-sidebarWidth} - @{xf-sidebarSpacer}');

			@media (min-width: @xf-pageWidthMax)
			{
				// window wider than the max width, so limit to the display area without the sidebar
				max-width: calc(~'@{xf-pageWidthMax} - @{xf-pageEdgeSpacer} - @{xf-pageEdgeSpacer} - @{xf-sidebarWidth} - @{xf-sidebarSpacer}');
			}

			@media (max-width: @xf-responsiveWide)
			{
				// sidebar/sidenav have been moved/hidden
				max-width: 100vw;
			}
		}
	}
}

.p-body-pageContent
{
	> .tabs--standalone:first-child
	{
		margin-bottom: 30px;
		box-shadow: 0px 5px 50px -10px rgba(0, 0, 0, 0.1);
	}
}

.p-body-sideNav
{
	display: table-cell;
	vertical-align: top;
	width: @xf-sidebarWidth;
}

.p-body-sideNavTrigger
{
	display: none;
}

.p-body-sidebar
{
	display: table-cell;
	vertical-align: top;
	width: @xf-sidebarWidth;

	.contentRow-figure .avatar--m
	{
		// make these avatars a bit smaller in the sidebar so the content has more space
		.m-avatarSize(@avatar-m * 2 / 3);
	}
}

.p-body-sideNavCol,
.p-body-contentCol,
.p-body-sidebarCol
{
	display: table-column;
}

.p-body-sideNavCol,
.p-body-sidebarCol
{
	width: @xf-sidebarWidth;
}

.p-body-content,
.p-body-pageContent,
.p-body-sideNav,
.p-body-sideNavContent,
.p-body-sidebar
{
	> :first-child
	{
		margin-top: 0;
	}

	> :last-child
	{
		margin-bottom: 0;
	}
}

@media (max-width: @xf-responsiveWide)
{
	.p-body-sideNavCol,
	.p-body-contentCol,
	.p-body-sidebarCol
	{
		display: none;
		width: auto;
	}

	.p-body-main,
	.p-body-content
	{
		display: block;
	}

	.p-body-sideNav
	{
		display: block;
		width: auto;
	}

	.p-body-sideNavTrigger
	{
		margin-bottom: ((@xf-elementSpacer) / 2);
		text-align: center;

		.button:before
		{
			.m-faBase();
			font-size: 120%;
			vertical-align: middle;
			display: inline-block;
			margin: -4px 6px -4px 0;
			.m-faContent(@fa-var-bars); //, .88em
		}

		.has-js &
		{
			display: block;
		}
	}

	.has-js .p-body-sideNavInner:not(.offCanvasMenu)
	{
		display: none;

		.m-transitionFadeDown();
	}

	.has-no-js .p-body-sideNavInner
	{
		margin-bottom: @xf-elementSpacer;
	}

	.p-body-sidebar
	{
		display: flex;
		flex-wrap: wrap;
		align-items: stretch;
		margin: (@xf-elementSpacer) -((@xf-pageEdgeSpacer) / 2) -(@xf-elementSpacer);
		width: auto;

		> *
		{
			margin: 0 ((@xf-pageEdgeSpacer) / 2) @xf-elementSpacer;
			min-width: @xf-sidebarWidth;
			flex: 1 1 @xf-sidebarWidth;

			&:last-child
			{
				margin-bottom: @xf-elementSpacer;
			}
		}

		// add an invisible block to ensure that the last row has the correct widths
		&:after
		{
			display: block;
			content: '';
			height: 0;
			margin: 0 ((@xf-pageEdgeSpacer) / 2);
			min-width: @xf-sidebarWidth;
			flex: 1 1 @xf-sidebarWidth;
		}

		.block-container
		{
			display: flex;
			flex-direction: column;
			height: 100%;

			.block-footer
			{
				margin-top: auto;
			}
		}
	}

	.p-body-main--withSideNav,
	.p-body-main--withSidebar
	{
		.p-body-content { padding: 0; }
	}
}

@media (max-width: @xf-responsiveEdgeSpacerRemoval)
{
	.p-body-sideNavContent
	{
		// this is likely to contain blocks that overflow the container so account for that
		margin: 0 -@xf-pageEdgeSpacer;
		padding: 0 @xf-pageEdgeSpacer;

		.offCanvasMenu &
		{
			margin: 0;
			padding: 0;
		}
	}

	.p-body-sidebar
	{
		display: block;
		margin-left: 0;
		margin-right: 0;

		> *
		{
			margin-left: 0;
			margin-right: 0;
			min-width: 0;
		}
	}
}

.p-breadcrumbs
{
	.m-listPlain();
	.m-clearFix();

	margin-bottom: 5px;
	line-height: 1.5;

	&.p-breadcrumbs--bottom
	{
		display: flex;
    	justify-content: center;
		margin-top: 0;
		margin-bottom: 20px;
	}

	> li
	{
		float: left;
		font-size: @xf-fontSizeSmall;

		a
		{
			display: inline-block;
			vertical-align: bottom;
			max-width: 300px;
			.m-overflowEllipsis();
		}

		&:after,
		&:before
		{
			.m-faBase();
			font-size: 90%;
			color: @xf-textColorMuted;
		}

		&:after
		{
			.m-faContent(@fa-var-angle-right, false ltr); //, .5em
			.m-faContent(@fa-var-angle-left, false, rtl); //, .5em
		}

		&:last-child
		{
			a
			{
				font-weight: @xf-fontWeightHeavy;
			}
		}
	}
}

@media (max-width: @xf-responsiveMedium)
{
	.p-breadcrumbs > li a
	{
		max-width: 200px;
	}
}

@media (max-width: @xf-responsiveNarrow)
{
	.p-breadcrumbs
	{
		> li
		{
			display: none;
			font-size: @xf-fontSizeSmallest;

			&:last-child
			{
				display: block;
			}

			a
			{
				max-width: 90vw;
			}

			&:after
			{
				display: none;
			}

			&:before
			{
				.m-faContent(@fa-var-chevron-left, false, ltr);
				.m-faContent(@fa-var-chevron-right, false, rtl);
				margin-right: .5em;
			}
		}
	}
}

// MAIN HEADER ROW

.p-header
{
	.xf-publicHeader();

	a
	{
		color: inherit;
	}
}

.p-header-inner
{
	.m-pageWidth();
	.m-pageInset();
}

.p-header-content
{
	padding: @xf-paddingMedium 0;

	display: flex;
	flex-wrap: wrap;
	justify-content: space-between;
	align-items: center;
	max-width: 100%;
}

.p-header-logo
{
	vertical-align: middle;
	margin-right: auto;

	a
	{
		color: inherit;
		text-decoration: none;
	}

	&.p-header-logo--text
	{
		font-size: @xf-fontSizeLargest;
	}

	&.p-header-logo--image
	{
		img
		{
			vertical-align: bottom;
			max-width: 100%;

			// Note: this is XF template syntax, not LESS
			{{ !property('publicLogoHeight') ? 'max-height: 200px;' : ''}}

			&[src$="/xenforo-logo.svg"]
			{
				height: 36px;
			}
		}
	}
}



@media (max-width: @xf-responsiveNarrow)
{
	.p-header-logo
	{
		max-width: 100px;

		&.p-header-logo--text
		{
			font-size: @xf-fontSizeLarge;
			font-weight: @xf-fontWeightNormal;
			.m-overflowEllipsis();
		}
	}
}

// navEl / Navigation Elements for header navigation

.p-navEl
{
	.m-clearFix();
}

.p-navEl-linkHolder
{
	float: left;
}

.p-navEl-link
{
	float: left;
	.m-transition(opacity, background; @_nav-elTransitionSpeed);

	&.p-navEl-link--menuTrigger
	{
		cursor: pointer;

		&:after
		{
			.m-menuGadget(); // .58em
			opacity: .5;
			.m-transition(opacity; @_nav-elTransitionSpeed);
		}

		&:hover:after
		{
			opacity: 1;
		}
	}
}

.p-navEl-splitTrigger
{
	float: left;
	opacity: .5;
	cursor: pointer;
	text-decoration: none;
	.m-transition(all; @_nav-elTransitionSpeed);

	&:after
	{
		.m-menuGadget(); // .58em
		line-height: 1;
	}

	&:hover
	{
		opacity: 1;
		text-decoration: none;
	}
}

// HEADER NAV ROW

.p-nav
{
	.xf-publicNav();

	a
	{
		color: inherit;
	}

	.p-navSticky.is-sticky &
	{
		.p-nav-list .p-navEl.is-selected,
		.p-account
		{
			border-radius: 0;
		}
	}
}

.p-nav-inner
{
	.m-pageWidth();
	.m-pageInset(0px);
	.m-clearFix();
	display: flex;
	align-items: center;
	padding: 25px 0px;
}



.p-nav .p-nav-menuTrigger
{
	display: none;
	vertical-align: middle;
	align-self: center;
	margin-left: max(0px, @xf-pageEdgeSpacer - 6px);
	margin-right: 5px;
	padding: @xf-publicNavPaddingV 8px;
	color: inherit;

	&:hover
	{
		text-decoration: none;
	}

	i:after
	{
		.m-faBase();
		font-size: @xf-fontSizeLargest;
		.m-faContent(@fa-var-bars); //, .88em
		vertical-align: bottom;
	}

	.p-nav-menuText
	{
		display: none;
	}
}

.p-nav-smallLogo
{
	<xf:if is="(property('arp_hideLogo'))">display: none;</xf:if>
	max-width: 100px;
	align-self: center;

	img
	{
		display: block;
		max-height: @header-navHeight;

		&:not([src$=".svg"])
		{
			width: auto;
		}
	}
}

.p-nav-scroller
{
	margin-right: auto;
	max-width: 100%;

	.hScroller-scroll:not(.is-calculated)
	{
		// IE11 seems to want to flash a vertical scrollbar without this here
		overflow: hidden;
	}

	.hScroller-action
	{
		.m-hScrollerActionColorVariation(
			xf-default(@xf-publicNav--background-color, transparent),
			xf-default(@xf-publicNav--color, ~""),
			xf-intensify(@xf-publicNav--color, 10%)
		);
	}
}

.p-nav-list
{
	.m-listPlain();
	.m-clearFix();

	font-size: 0;

	// this applies padding that will be contained within the scroller.
	// it needs font-size 0 to not create extra space though
	&:before,
	&:after
	{
		display: inline-block;
		width: @xf-pageEdgeSpacer;
		content: '';
	}

	> li
	{
		display: inline-block;
		vertical-align: bottom;
		font-size: @xf-fontSizeNormal;

		&:first-child
		{
			margin-left: 0;
		}
	}

	.m-navElHPadding(@xf-publicNavPaddingH);

	.p-navEl
	{
		.xf-publicNavTab();
		.m-transition(all; @_nav-elTransitionSpeed);

		&.is-selected
		{
			.xf-publicNavSelected();

			.p-navEl-link
			{
				padding-right: @xf-publicNavPaddingH; // since the split trigger is hidden

				&:hover
				{
					background: none;
					text-decoration: none;
				}
			}

			.p-navEl-splitTrigger
			{
				display: block;
			}
		}

		&:not(.is-selected):not(.is-menuOpen)
		{
			&:hover,
			.p-navEl-link:hover,
			.p-navEl-splitTrigger:hover
			{
				.xf-publicNavTabHover();
			}
		}

		&.is-menuOpen
		{
			.xf-publicNavTabMenuOpen();

			//border-top-left-radius: xf-default(@xf-publicNavSelected--border-top-left-radius, 0);
			//border-top-right-radius: xf-default(@xf-publicNavSelected--border-top-right-radius, 0);

			//.m-dropShadow(0, 5px, 10px, 0, .35);

			a
			{
				text-decoration: none;
				opacity: 1;
			}
		}
	}

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		padding-top: @xf-publicNavPaddingV;
		padding-bottom: @xf-publicNavPaddingV;
	}
}

.p-navSticky--primary.is-sticky
{
	.p-nav-list
	{
		.p-navEl-link.p-navEl-link--splitMenu
		{
			padding-right: ((@xf-publicNavPaddingH) / 4);
		}

		.p-navEl.is-selected .p-navEl-splitTrigger
		{
			display: inline;
			position: relative;

			&:before
			{
				content: '';
				position: absolute;
				left: 0;
				top: 5px;
				bottom: 5px;
				width: 0;
				border-left: @xf-borderSize solid fade(xf-default(@xf-publicNavSelected--color, transparent), 35%);
			}
		}
	}
}

@media (max-width: @xf-publicNavCollapseWidth)
{
	.has-js
	{
		.p-nav-inner
		{
			min-height: 45px;
		}

		.p-nav .p-nav-menuTrigger
		{
			display: inline-block;
		}

		.p-nav-smallLogo
		{
			display: inline-block;
		}

		.p-nav-scroller
		{
			display: none;
		}
	}
}

// ACCOUNT/VISITOR/SEARCH SECTION

.p-nav-opposite
{
	margin-left: auto;
	margin-right: @xf-pageEdgeSpacer;
	text-align: right;
	flex-shrink: 0;
}

.p-navgroup
{
	float: left;
	align-items: center;
	.m-clearFix();
	border-top-left-radius: @xf-borderRadiusMedium;
	border-top-right-radius: @xf-borderRadiusMedium;

	&.p-discovery
	{
		margin-left: .5em;

		&.p-discovery--noSearch
		{
			margin-left: 0;
		}
	}
}

.p-navgroup-link
{
	float: left;
	display: flex;
	padding: 0 15px;

	&:first-of-type
	{
		border-top-left-radius: @xf-borderRadiusMedium;
		border-left: none;
	}

	&:last-of-type
	{
		border-top-right-radius: @xf-borderRadiusMedium;
	}

	&:hover
	{
		text-decoration: none;
	}

	&.p-navgroup-link--user
	{
		.m-overflowEllipsis();
		max-width: 150px;

		.avatar
		{
			min-width: 25px;
    		min-height: 25px;
			font-size: 13px;
			border-radius: 100%;
		}
	}

	&.badgeContainer
	{
		position: relative;

		&:after
		{
			left: 10px;
    		top: 0px;
    		width: 10px;
    		height: 10px;
    		padding: 0px;
    		border-radius: 30px;
   	 		font-size: 0px;
    		line-height: 0px
		}

		&:hover,
		&.badgeContainer--highlighted
		{
			opacity: 1;
		}
	}

	&.is-menuOpen
	{
		.xf-publicNavTabMenuOpen();
		opacity: 1;
	}

	&.p-navgroup-link--iconic
	{
		i:after
		{
			.m-faBase();
			display: inline-block;
			min-width: 1.2em;
			text-align: center;
		}
	}

	&.p-navgroup-link--conversations i:after
	{
		.m-faContent(@fa-var-envelope, 1em);
	}

	&.p-navgroup-link--alerts i:after
	{
		.m-faContent(@fa-var-bell); //, .88em
	}

	&.p-navgroup-link--bookmarks i:after
	{
		.m-faContent(@fa-var-bookmark); //, .75em
	}

	&.p-navgroup-link--whatsnew i:after
	{
		.m-faContent(@fa-var-bolt); //, .63em
	}

	&.p-navgroup-link--search i:after
	{
		.m-faContent(@fa-var-search); //, 1em
	}
}

.p-navgroup-link--whatsnew
{
	display: none;

	.p-navgroup-link:first-of-type& + .p-navgroup-link
	{
		border-top-left-radius: @xf-borderRadiusMedium;
		border-left: none;
	}
}

@media (max-width: @xf-responsiveWide)
{
	.p-navgroup-link
	{
		&.p-navgroup-link--iconic .p-navgroup-linkText,
		&.p-navgroup-link--textual i
		{
			display: none;
		}

		&.p-navgroup-link--textual
		{
			.m-overflowEllipsis();
			max-width: 110px;
		}

		&.p-navgroup-link--iconic i:after
		{
			text-align: center;
		}
	}
}

@media (max-width: @xf-publicNavCollapseWidth)
{
	.p-navgroup-link--whatsnew
	{
		display: block;
	}

	.has-js
	{
		.p-nav-opposite
		{
			align-self: center;
			margin-right: max(0px, @xf-pageEdgeSpacer - 6px);

			.p-navgroup
			{
				background: none;
				margin-left: 0;
			}

			.p-navgroup-link
			{
				border: none;
				border-radius: @xf-borderRadiusMedium;

				&.is-menuOpen
				{
					.m-borderBottomRadius(0);
				}

				&.badgeContainer
				{
					opacity: 1;
				}
			}
		}
	}
}

@media (max-width: 359px)
{
	.p-navgroup-link&.p-navgroup-link--user
	{
		display: none;
	}
}

@media (max-width: 374px)
{
	.p-navgroup-link.p-navgroup-link--register
	{
		display: none;
	}
}

@_bbCodeBlock-spacing: .5em;
@_bbCodeBlock-paddingV: @xf-paddingMedium;
@_bbCodeBlock-paddingH: @xf-paddingLarge;
@_bbCodeBlock-expandTriggerHeight: (@xf-bbCodeBlockExpandHeight) / 2;

.bbCodeBlock
{
	display: flow-root;
	margin: @_bbCodeBlock-spacing 0;
	padding: 18px 20px;
	.xf-bbCodeBlock();

	&.bbCodeBlock--quote
	{
		.bbCodeBlock-content
		{
			font-size: @xf-fontSizeSmall;
		}
	}
}

.bbCodeBlock-title
{
	padding-bottom: 10px;
	.xf-bbCodeBlockTitle();
	.m-clearFix();
}

a.bbCodeBlock-sourceJump
{
	color: inherit;
	text-decoration: none;

	&:hover
	{
		text-decoration: underline;
	}

	&:after
	{
		.m-faBase();
		.m-faContent(@fa-var-arrow-circle-up); //, 1em
		display: inline-block;
		margin-left: 5px;
	}
}

.bbCodeBlock-content
{
	position: relative;
	.m-clearFix();
}

.bbCodeBlock-expandLink
{
	display: none;
	position: absolute;
	top: (@xf-bbCodeBlockExpandHeight) + (@_bbCodeBlock-paddingV * 2) - (@_bbCodeBlock-expandTriggerHeight);
	left: 0;
	right: 0;
	height: @_bbCodeBlock-expandTriggerHeight;
	cursor: pointer;
	z-index: @zIndex-1;

	.m-gradient(
		fade(@xf-bbCodeBlock--background-color, 0%),
		xf-default(@xf-bbCodeBlock--background-color, transparent),
		transparent,
		0%,
		80%
	);

	a
	{
		position: absolute;
		bottom: @_bbCodeBlock-paddingV;
		left: 0;
		right: 0;
		text-align: center;
		font-size: @xf-fontSizeSmall;
		color: @xf-textColorAttention;
		text-decoration: none;
	}
}

.bbCodeBlock--screenLimited
{
	.bbCodeBlock-content
	{
		max-height: 300px;
		max-height: 70vh;
		overflow: auto;
		-webkit-overflow-scrolling: touch;
	}
}

.bbCodeBlock--expandable
{
	overflow: hidden;
	.m-transition(-xf-height, height, padding, margin, border;);

	.bbCodeBlock-content
	{
		overflow: hidden;

		.bbCodeBlock:not(.bbCodeBlock--expandable) .bbCodeBlock-content
		{
			overflow: visible;
		}
		.bbCodeBlock.bbCodeBlock--screenLimited .bbCodeBlock-content
		{
			overflow: auto;
		}
	}

	.bbCodeBlock-expandContent
	{
		max-height: @xf-bbCodeBlockExpandHeight;
		overflow: hidden;
	}

	&.is-expandable
	{
		.bbCodeBlock-expandLink
		{
			display: block;
		}
	}

	&.is-expanded
	{
		.bbCodeBlock-expandContent
		{
			max-height: none;
		}

		.bbCodeBlock-expandLink
		{
			display: none;
		}
	}
}

.bbCodeBlock--unfurl
{
	.xf-contentHighlightBase();

	padding: @_bbCodeBlock-paddingV;
	width: 650px;
	max-width: 100%;
	border-left: @xf-borderSizeMinorFeature solid @xf-borderColorFeature;

	overflow: hidden;

	.contentRow-header
	{
		margin: 0;
		font-size: @xf-fontSizeNormal;
		font-weight: normal;
		.m-overflowEllipsis();
	}

	.contentRow-snippet
	{
		font-size: @xf-fontSizeSmaller;
		font-style: normal;
	}

	.contentRow-minor
	{
		font-size: @xf-fontSizeSmaller;
	}

	&.is-pending
	{
		opacity: 0.5;

		&.is-recrawl
		{
			opacity: 1;
		}
	}

	&.is-simple
	{
		.contentRow-figure
		{
			display: none;
		}
	}

	.bbCodeBlockUnfurl-icon
	{
		width: 12px;
		vertical-align: -2px;
	}
}

.bbCodeCode
{
	margin: 0;
	padding: 0;

	.has-hiddenscroll &
	{
		// solely to workaround this Chrome bug: https://bugs.chromium.org/p/chromium/issues/detail?id=914844
		// TODO: remove when fixed
		padding-bottom: @xf-paddingLarge;
	}

	font-family: @xf-fontFamilyCode;
	font-size: @xf-fontSizeSmall;
	line-height: @xf-lineHeightDefault;
	-ltr-rtl-text-align: left;

	direction: ltr;
	white-space: pre;
	position: relative;

	.m-tabSize();

	code
	{
		font-family: inherit;
	}

	.prism-token
	{
		&.prism-comment,
		&.prism-prolog,
		&.prism-doctype,
		&.prism-cdata
		{
			& when (@xf-styleType = light) { color: #a50; }
			& when (@xf-styleType = dark) { color: #8292a2; }
		}

		&.prism-constant
		{
			& when (@xf-styleType = light) { color: #05a; }
			& when (@xf-styleType = dark) { color: #f92672; }
		}

		&.prism-tag
		{
			& when (@xf-styleType = light) { color: #170; }
			& when (@xf-styleType = dark) { color: #f92672; }
		}

		&.prism-boolean
		{
			& when (@xf-styleType = light) { color: #219; }
			& when (@xf-styleType = dark) { color: #ae81ff; }
		}

		&.prism-symbol,
		&.prism-atrule,
		&.prism-keyword
		{
			& when (@xf-styleType = light) { color: #708; }
			& when (@xf-styleType = dark) { color: #e6db74; }
		}

		&.prism-selector,
		&.prism-function
		{
			& when (@xf-styleType = light) { color: #05a; }
			& when (@xf-styleType = dark) { color: #e6db74; }
		}

		&.prism-deleted
		{
			color: #d44;
		}

		&.prism-inserted
		{
			color: #292;
		}

		&.prism-string,
		&.prism-attr-value
		{
			& when (@xf-styleType = light) { color: #a11; }
			& when (@xf-styleType = dark) { color: #a6e22e; }
		}

		&.prism-number
		{
			& when (@xf-styleType = light) { color: #164; }
			& when (@xf-styleType = dark) { color: #ae81ff; }
		}

		&.prism-attr-name,
		&.prism-char,
		&.prism-builtin
		{
			& when (@xf-styleType = light) { color: #00c; }
			& when (@xf-styleType = dark) { color: #a6e22e; }
		}

		&.prism-regex,
		&.prism-important,
		&.prism-variable,
		&.prism-package
		{
			& when (@xf-styleType = light) { color: #05a; }
			& when (@xf-styleType = dark) { color: #fd971f; }
		}

		&.prism-class-name,
		&.prism-important,
		&.prism-bold
		{
			& when (@xf-styleType = light) { color: #00f; }
			& when (@xf-styleType = dark) { color: #e6db74; }
		}

		&.prism-bold
		{
			font-weight: bold;
		}

		&.prism-italic,
		&.prism-constant
		{
			& when (@xf-styleType = light) { color: #05a; }
			& when (@xf-styleType = dark) { color: #f92672; }

			font-style: italic;
		}

		&.prism-entity
		{
			cursor: help;
		}
	}
}

.bbCodeInline
{
	margin: 0;
	.xf-bbCodeInlineCode();
	font-family: @xf-fontFamilyCode;
	line-height: @xf-lineHeightDefault;
	box-decoration-break: clone;
	-webkit-box-decoration-break: clone;
	white-space: pre-wrap;
}

.bbCodeSpoiler
{
	margin: @_bbCodeBlock-spacing 0;
}

.bbCodeSpoiler-button
{
	.has-no-js & { display: none; background-color: #f5f5f5; }
}

.bbCodeSpoiler-content
{
	.m-hiddenEl(true);
	.has-no-js & { display: block !important; }

	> .bbCodeBlock--spoiler
	{
		margin: .2em 0 0;
	}
}

.bbCodeInlineSpoiler
{
	@blurAmount: 6px;
	filter: blur(@blurAmount);
	cursor: pointer;

	a, span
	{
		.has-js &
		{
			pointer-events: none;
		}
	}

	.smilie
	{
		filter: grayscale(90%);
	}

	&:hover
	{
		filter: blur((@blurAmount - 1));
	}
}

.bbCodeSpoiler .bbCodeSpoiler-wrapper {
    background-color: #f5f5f5;
}

// ########################## GLOBAL BASE SETUP #######################

html
{
	font: @xf-fontSizeNormal / @xf-lineHeightDefault sans-serif;
	font-family: @xf-fontFamilyUi;
	font-weight: @xf-fontWeightNormal;
	color: @xf-textColor;
	margin: 0;
	padding: 0;
	word-wrap: break-word;
	background-color: @xf-pageBg;

	/* // just a reminder that we *might* want this at some point
	-ms-text-size-adjust: none;
	-webkit-text-size-adjust: none;*/
}

button, input, optgroup, select, textarea
{
	font-family: @xf-fontFamilyUi;
	line-height: @xf-lineHeightDefault;
}

img
{
	max-width: 100%;
	height: auto;
}

b, strong
{
	font-weight: @xf-fontWeightHeavy;
}

a
{
	.xf-link();

	&:hover
	{
		.xf-linkHover();
	}
}

svg
{
	fill: currentColor;
}

